-- MP-0044: guarded editorial content import. Deploy portrait/logo assets first.

begin;

do $$ begin
 if not exists(select 1 from public.entities where slug='dap' and type='party') then raise exception 'MP-0044: missing or wrong parent'; end if;
 if not exists(select 1 from public.entities where slug='pkr' and type='party') then raise exception 'MP-0044: missing or wrong parent'; end if;
 if not exists(select 1 from public.entities where slug='umno' and type='party') then raise exception 'MP-0044: missing or wrong parent'; end if;
 if exists(select 1 from public.entities where slug in ('onn-abu-bakar','hasni-mohammad','wong-shu-qi') and (type <> 'politician' or owner_id is not null)) then raise exception 'MP-0044: ownership or type conflict'; end if;
 if exists(select 1 from public.entities where type='politician' and lower(constituency) in ('batu pahat','simpang renggam','kluang') and slug not in ('onn-abu-bakar','hasni-mohammad','wong-shu-qi')) then raise exception 'MP-0044: constituency identity conflict'; end if;
 if exists(select 1 from public.milestones m join public.entities e on e.id=m.entity_id where m.import_key like 'MP-0044:%' and (m.source_type <> 'editorial' or e.slug not in ('onn-abu-bakar','hasni-mohammad','wong-shu-qi') or m.import_key not like 'MP-0044:' || e.slug || ':%')) then raise exception 'MP-0044: milestone identity conflict'; end if;
end $$;

insert into public.entities (type,parent_id,slug,name,bloc,position,constituency,state,description,website,photo_path,photo_source_url,photo_credit,profile_checked_at,profile_sources) select 'politician',parent.id,'onn-abu-bakar','Onn Abu Bakar','government','Member of the Dewan Rakyat','Batu Pahat','Johor','Onn Abu Bakar represents Batu Pahat, Johor, in the Dewan Rakyat. Affiliated with PKR.','https://www.parlimen.gov.my/profile-ahli.html?uweb=dr&id=4189','/portraits/onn-abu-bakar.webp','https://www.parlimen.gov.my/images/webuser/ahli/2022/P150.jpg','Parliament of Malaysia','2026-11-10','[{"label": "Parliament · official current profile", "url": "https://www.parlimen.gov.my/profile-ahli.html?uweb=dr&id=4189"}, {"label": "PKR · current parliamentary representatives", "url": "https://keadilanrakyat.org/wakil-rakyat/"}]'::jsonb from public.entities parent where parent.slug='pkr' and parent.type='party' on conflict (slug) do update set parent_id=excluded.parent_id,name=excluded.name,bloc=excluded.bloc,position=excluded.position,constituency=excluded.constituency,state=excluded.state,description=excluded.description,website=excluded.website,photo_path=excluded.photo_path,photo_source_url=excluded.photo_source_url,photo_credit=excluded.photo_credit,profile_checked_at=excluded.profile_checked_at,profile_sources=excluded.profile_sources where public.entities.type='politician' and public.entities.owner_id is null and ROW(public.entities.parent_id,public.entities.name,public.entities.bloc,public.entities.position,public.entities.constituency,public.entities.state,public.entities.description,public.entities.website,public.entities.photo_path,public.entities.photo_source_url,public.entities.photo_credit,public.entities.profile_checked_at,public.entities.profile_sources) IS DISTINCT FROM ROW(excluded.parent_id,excluded.name,excluded.bloc,excluded.position,excluded.constituency,excluded.state,excluded.description,excluded.website,excluded.photo_path,excluded.photo_source_url,excluded.photo_credit,excluded.profile_checked_at,excluded.profile_sources);

insert into public.entities (type,parent_id,slug,name,bloc,position,constituency,state,description,website,photo_path,photo_source_url,photo_credit,profile_checked_at,profile_sources) select 'politician',parent.id,'hasni-mohammad','Hasni Mohammad','government','Member of the Dewan Rakyat; Chair of the Malaysian Highway Authority (LLM)','Simpang Renggam','Johor','Hasni Mohammad represents Simpang Renggam, Johor, in the Dewan Rakyat. Current role: Member of the Dewan Rakyat; Chair of the Malaysian Highway Authority (LLM). Affiliated with UMNO.','https://www.parlimen.gov.my/profile-ahli.html?uweb=dr&id=4190','/portraits/hasni-mohammad.webp','https://www.parlimen.gov.my/images/webuser/ahli/2022/P151.png','Parliament of Malaysia','2026-11-10','[{"label": "Parliament · official current profile", "url": "https://www.parlimen.gov.my/profile-ahli.html?uweb=dr&id=4190"}, {"label": "UMNO · personal party statement, 12 March 2026", "url": "https://www.sinarharian.com.my/article/771440/berita/politik/rumah-bangsa-inisiatif-umno-untuk-semua---hasni"}, {"label": "LLM · chair’s current term, November 2025–November 2027", "url": "https://www.llm.gov.my/corporate_info/director"}]'::jsonb from public.entities parent where parent.slug='umno' and parent.type='party' on conflict (slug) do update set parent_id=excluded.parent_id,name=excluded.name,bloc=excluded.bloc,position=excluded.position,constituency=excluded.constituency,state=excluded.state,description=excluded.description,website=excluded.website,photo_path=excluded.photo_path,photo_source_url=excluded.photo_source_url,photo_credit=excluded.photo_credit,profile_checked_at=excluded.profile_checked_at,profile_sources=excluded.profile_sources where public.entities.type='politician' and public.entities.owner_id is null and ROW(public.entities.parent_id,public.entities.name,public.entities.bloc,public.entities.position,public.entities.constituency,public.entities.state,public.entities.description,public.entities.website,public.entities.photo_path,public.entities.photo_source_url,public.entities.photo_credit,public.entities.profile_checked_at,public.entities.profile_sources) IS DISTINCT FROM ROW(excluded.parent_id,excluded.name,excluded.bloc,excluded.position,excluded.constituency,excluded.state,excluded.description,excluded.website,excluded.photo_path,excluded.photo_source_url,excluded.photo_credit,excluded.profile_checked_at,excluded.profile_sources);

insert into public.entities (type,parent_id,slug,name,bloc,position,constituency,state,description,website,photo_path,photo_source_url,photo_credit,profile_checked_at,profile_sources) select 'politician',parent.id,'wong-shu-qi','Wong Shu Qi','government','Member of the Dewan Rakyat','Kluang','Johor','Wong Shu Qi represents Kluang, Johor, in the Dewan Rakyat. Affiliated with DAP.','https://www.parlimen.gov.my/profile-ahli.html?uweb=dr&id=4191','/portraits/wong-shu-qi.webp','https://www.parlimen.gov.my/images/webuser/ahli/2022/P152.jpg','Parliament of Malaysia','2026-11-10','[{"label": "Parliament · official current profile", "url": "https://www.parlimen.gov.my/profile-ahli.html?uweb=dr&id=4191"}, {"label": "DAP · current Johor representatives", "url": "https://dapmalaysia.org/johor-representatives/"}]'::jsonb from public.entities parent where parent.slug='dap' and parent.type='party' on conflict (slug) do update set parent_id=excluded.parent_id,name=excluded.name,bloc=excluded.bloc,position=excluded.position,constituency=excluded.constituency,state=excluded.state,description=excluded.description,website=excluded.website,photo_path=excluded.photo_path,photo_source_url=excluded.photo_source_url,photo_credit=excluded.photo_credit,profile_checked_at=excluded.profile_checked_at,profile_sources=excluded.profile_sources where public.entities.type='politician' and public.entities.owner_id is null and ROW(public.entities.parent_id,public.entities.name,public.entities.bloc,public.entities.position,public.entities.constituency,public.entities.state,public.entities.description,public.entities.website,public.entities.photo_path,public.entities.photo_source_url,public.entities.photo_credit,public.entities.profile_checked_at,public.entities.profile_sources) IS DISTINCT FROM ROW(excluded.parent_id,excluded.name,excluded.bloc,excluded.position,excluded.constituency,excluded.state,excluded.description,excluded.website,excluded.photo_path,excluded.photo_source_url,excluded.photo_credit,excluded.profile_checked_at,excluded.profile_sources);

do $$ begin if (select count(*) from public.entities where slug in ('onn-abu-bakar','hasni-mohammad','wong-shu-qi') and type='politician' and owner_id is null) <> 3 then raise exception 'MP-0044: concurrent ownership or identity change'; end if; end $$;

commit;
